// 선택할 수 있는 프레임 디자인 목록입니다 (모든 사진 영역이 4:3 비율로 맞춰진 캐릭터 프레임 3종 + 기본 프레임 2종).
const FRAMES = [
  {
    name: 'puppy-booth',
    label: '강아지 프레임',
    category: '화이트·레드',
    isImageFrame: true,
    width: 682,
    height: 1669,
    slots: [
      { x: 102, y: 112, w: 479, h: 359 },
      { x: 102, y: 484, w: 479, h: 359 },
      { x: 104, y: 855, w: 477, h: 358 },
      { x: 103, y: 1228, w: 477, h: 358 }
    ]
  },
  {
    name: 'kitty-booth',
    label: '고양이 프레임',
    category: '퍼플·블랙',
    isImageFrame: true,
    width: 682,
    height: 1675,
    slots: [
      { x: 102, y: 113, w: 480, h: 360 },
      { x: 102, y: 487, w: 480, h: 360 },
      { x: 103, y: 861, w: 479, h: 359 },
      { x: 103, y: 1235, w: 478, h: 358 }
    ]
  },
  {
    name: 'hamster-cheese',
    label: '햄스터 프레임',
    category: '베이지·브라운',
    isImageFrame: true,
    width: 682,
    height: 1934,
    slots: [
      { x: 59, y: 99, w: 564, h: 423 },
      { x: 59, y: 538, w: 564, h: 423 },
      { x: 59, y: 976, w: 565, h: 424 },
      { x: 59, y: 1416, w: 564, h: 423 }
    ]
  },
  {
    name: 'classic-white',
    label: '기본 화이트',
    category: '기본',
    isImageFrame: false
  },
  {
    name: 'classic-dark',
    label: '기본 블랙',
    category: '기본',
    isImageFrame: false
  }
];

// 원본 이미지에서 사진 영역 4칸을 모두 4:3 비율로 확장하고 투명 처리한 전체 프레임 데이터입니다.
const FRAME_LAYER_DATA = {
  'puppy-booth': {
    frameSrc: 'data:image/png;base64,'
  },
  'kitty-booth': {
    frameSrc: 'data:image/png;base64,'
  },
  'hamster-cheese': {
    frameSrc: 'data:image/png;base64,'
  }
};

// 미리 불러온 전체 투명 프레임 Image 객체와 추출된 컷별 4:3 캐릭터 오버레이 캐시입니다.
const loadedFrameImages = {};
const cutOverlayCache = {};

// 프레임 이름표(frameName)로 FRAMES 목록에서 해당 프레임 설정 객체를 찾아 돌려주는 함수입니다.
function findFrameConfig(frameName) {
  for (let i = 0; i < FRAMES.length; i += 1) {
    if (FRAMES[i].name === frameName) {
      return FRAMES[i];
    }
  }
  return FRAMES[0];
}

// 4:3 비율 투명 프레임 이미지에서 각 컷(0~3)의 4:3 사진 영역 안 캐릭터만 테두리 없이 투명 PNG Data URL로 추출하는 함수입니다.
function buildCutOverlaysForFrame(frameName, img) {
  const cfg = findFrameConfig(frameName);
  if (!cfg || !cfg.isImageFrame || !img || !img.width) return;

  cutOverlayCache[frameName] = [];

  for (let s = 0; s < 4; s += 1) {
    const sr = cfg.slots[s];
    const cutCanvas = document.createElement('canvas');
    cutCanvas.width = sr.w;
    cutCanvas.height = sr.h;
    const ctx = cutCanvas.getContext('2d');

    ctx.drawImage(img, sr.x, sr.y, sr.w, sr.h, 0, 0, sr.w, sr.h);

    // 바깥 프레임 테두리선과 반대편 여백 장식은 지우고 현재 컷의 캐릭터만 남깁니다.
    ctx.clearRect(0, 0, sr.w, 10);
    ctx.clearRect(0, sr.h - 3, sr.w, 3);
    ctx.clearRect(0, 0, 6, sr.h);
    ctx.clearRect(sr.w - 6, 0, 6, sr.h);

    const isLeftChar = s % 2 === 0;
    if (isLeftChar) {
      const clearX = Math.round(sr.w * 0.68);
      ctx.clearRect(clearX, 0, sr.w - clearX, sr.h);
    } else {
      const clearW = Math.round(sr.w * 0.28);
      ctx.clearRect(0, 0, clearW, sr.h);
    }

    cutOverlayCache[frameName].push(cutCanvas.toDataURL('image/png'));
  }
}

// 앱이 시작될 때 3가지 캐릭터 프레임 이미지를 미리 메모리에 준비하고 컷별 4:3 캐릭터를 분리해 두는 함수입니다.
function preloadFrameImages() {
  const names = ['puppy-booth', 'kitty-booth', 'hamster-cheese'];
  for (let i = 0; i < names.length; i += 1) {
    (function (name) {
      const img = new Image();
      img.onload = function () {
        buildCutOverlaysForFrame(name, img);
        if (typeof updateLiveCharacterOverlay === 'function' && typeof state !== 'undefined') {
          updateLiveCharacterOverlay(state.currentCutIndex || 0);
        }
      };
      img.src = FRAME_LAYER_DATA[name].frameSrc;
      loadedFrameImages[name] = img;
    })(names[i]);
  }
}

preloadFrameImages();

// 현재 선택한 프레임(frameName)과 컷 번호(cutIndex: 0~3)에 해당하는 실시간 4:3 캐릭터 오버레이 이미지 주소를 돌려주는 함수입니다.
function getCutCharacterOverlay(frameName, cutIndex, totalCuts) {
  if (totalCuts && totalCuts !== 4) {
    return null;
  }
  const idx = Math.max(0, Math.min(3, cutIndex || 0));

  if (!cutOverlayCache[frameName] && loadedFrameImages[frameName] && loadedFrameImages[frameName].complete) {
    buildCutOverlaysForFrame(frameName, loadedFrameImages[frameName]);
  }

  if (cutOverlayCache[frameName] && cutOverlayCache[frameName][idx]) {
    return cutOverlayCache[frameName][idx];
  }
  return null;
}

// 모든 촬영 화면과 사진 칸을 4:3 비율로 통일하여 돌려주는 함수입니다.
function getFrameSlotAspectRatio() {
  return '4 / 3';
}

// 오늘 날짜를 '2026.11.22' 같은 'YYYY.MM.DD' 형식으로 만들어 돌려주는 함수입니다.
function formatTodayDate() {
  const now = new Date();
  const year = now.getFullYear();
  const month = String(now.getMonth() + 1).padStart(2, '0');
  const day = String(now.getDate()).padStart(2, '0');
  return year + '.' + month + '.' + day;
}

// 카메라 미리보기(4:3 비율)와 잘림 영역이 100% 일치하도록 사진(shot)을 목표 4:3 영역(dx, dy, dw, dh)에 그려 주는 함수입니다.
function drawPhotoCover(ctx, shot, dx, dy, dw, dh) {
  if (!shot) return;
  const sw = shot.width || dw;
  const sh = shot.height || dh;
  const srcRatio = sw / sh;
  const dstRatio = dw / dh;

  let cropW = sw;
  let cropH = sh;
  let cropX = 0;
  let cropY = 0;

  if (srcRatio > dstRatio) {
    cropW = sh * dstRatio;
    cropX = (sw - cropW) / 2;
  } else if (srcRatio < dstRatio) {
    cropH = sw / dstRatio;
    cropY = (sh - cropH) / 2;
  }

  ctx.drawImage(shot, cropX, cropY, cropW, cropH, dx, dy, dw, dh);
}

// 찍은 4:3 캔버스 목록(shots)과 선택한 프레임 이름표(frameName)를 받아 4:3 투명 프레임과 캐릭터를 자연스럽게 합성한 세로 프레임 캔버스를 돌려주는 함수입니다.
function makeStrip(shots, frameName) {
  const count = shots && shots.length ? shots.length : 4;
  const activeFrame =
    frameName ||
    (typeof state !== 'undefined' && state.frame ? state.frame : 'puppy-booth');
  const cfg = findFrameConfig(activeFrame);

  if (cfg && cfg.isImageFrame && count === 4) {
    const stripCanvas = document.createElement('canvas');
    stripCanvas.width = cfg.width;
    stripCanvas.height = cfg.height;
    const ctx = stripCanvas.getContext('2d');

    ctx.fillStyle = activeFrame === 'hamster-cheese' ? '#faebd7' : '#faf7f2';
    ctx.fillRect(0, 0, cfg.width, cfg.height);

    for (let i = 0; i < 4; i += 1) {
      const slot = cfg.slots[i];
      const shot = shots[i];

      ctx.fillStyle = '#e5e7eb';
      ctx.fillRect(slot.x, slot.y, slot.w, slot.h);

      if (shot) {
        drawPhotoCover(ctx, shot, slot.x, slot.y, slot.w, slot.h);
      }
    }

    const frameImg = loadedFrameImages[activeFrame];
    if (frameImg && frameImg.complete && frameImg.naturalWidth > 0) {
      ctx.drawImage(frameImg, 0, 0, cfg.width, cfg.height);
    }

    return stripCanvas;
  }

  const stripCanvas = document.createElement('canvas');
  const totalWidth = 600;
  const outerPadding = 24;
  const gap = 14;
  const footerHeight = 90;

  const photoWidth = totalWidth - outerPadding * 2;
  const photoHeight = Math.round((photoWidth * 3) / 4);
  const totalHeight =
    outerPadding + photoHeight * count + gap * (count - 1) + footerHeight;

  stripCanvas.width = totalWidth;
  stripCanvas.height = totalHeight;

  const ctx = stripCanvas.getContext('2d');
  const isDark = activeFrame === 'classic-dark';

  ctx.fillStyle = isDark ? '#18181b' : '#ffffff';
  ctx.fillRect(0, 0, totalWidth, totalHeight);

  for (let i = 0; i < count; i += 1) {
    const shot = shots[i];
    const x = outerPadding;
    const y = outerPadding + i * (photoHeight + gap);

    ctx.fillStyle = '#e5e7eb';
    ctx.fillRect(x, y, photoWidth, photoHeight);

    if (shot) {
      drawPhotoCover(ctx, shot, x, y, photoWidth, photoHeight);
    }

    if (isDark) {
      ctx.lineWidth = 2;
      ctx.strokeStyle = '#3f3f46';
      ctx.strokeRect(x, y, photoWidth, photoHeight);
    }
  }

  const footerTop = totalHeight - footerHeight;
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';

  ctx.fillStyle = isDark ? '#ffffff' : '#111111';
  ctx.font =
    'bold 28px -apple-system, BlinkMacSystemFont, "Pretendard", "Apple SD Gothic Neo", "Malgun Gothic", sans-serif';
  ctx.fillText('인생네컷', totalWidth / 2, footerTop + 34);

  ctx.fillStyle = isDark ? '#a1a1aa' : '#666666';
  ctx.font =
    '500 18px -apple-system, BlinkMacSystemFont, "Pretendard", "Apple SD Gothic Neo", "Malgun Gothic", sans-serif';
  ctx.fillText(formatTodayDate(), totalWidth / 2, footerTop + 66);

  return stripCanvas;
}

// 프레임 선택 버튼 안에 보여 줄 미리보기 이미지 주소를 돌려주는 함수입니다.
function createFramePreviewDataUrl(frameName) {
  if (FRAME_LAYER_DATA[frameName] && FRAME_LAYER_DATA[frameName].frameSrc) {
    return FRAME_LAYER_DATA[frameName].frameSrc;
  }

  const dummyShots = [];
  for (let i = 0; i < 4; i += 1) {
    const sample = document.createElement('canvas');
    sample.width = 160;
    sample.height = 120;
    const sctx = sample.getContext('2d');
    sctx.fillStyle = '#e5e7eb';
    sctx.fillRect(0, 0, 160, 120);
    dummyShots.push(sample);
  }

  const fullStrip = makeStrip(dummyShots, frameName);
  const thumbCanvas = document.createElement('canvas');
  const targetW = 110;
  const targetH = Math.round((fullStrip.height / fullStrip.width) * targetW);

  thumbCanvas.width = targetW;
  thumbCanvas.height = targetH;

  const tctx = thumbCanvas.getContext('2d');
  tctx.drawImage(fullStrip, 0, 0, targetW, targetH);

  return thumbCanvas.toDataURL('image/png');
}